# ---- references: Criqui [1] and Gornik [2] removed, the rest renumbered 3-24 -> 1-22
import re as _re
def _txt(el):
    return "".join(t.text or "" for t in el.iter(db.qn("w:t")))
_cite = _re.compile(r"\[([0-9][0-9;–,\s]*)\]")
def _shift(m):
    nums = _re.split(r"([;–,]\s*)", m.group(1))
    out = []
    for tok in nums:
        if tok.strip().isdigit():
            n = int(tok); assert n >= 3, f"citation [{n}] still present"
            out.append(str(n - 2))
        else:
            out.append(tok)
    return "[" + "".join(out) + "]"
start = next(i for i, el in enumerate(b.out) if _txt(el).strip() == "Әдебиеттер тізімі")
keep_out = []
for i, el in enumerate(b.out):
    if i > start and _re.match(r"^\d+\. ", _txt(el)):
        first = next(t for t in el.iter(db.qn("w:t")) if t.text)
        m = _re.match(r"^(\d+)\.", first.text)
        assert m, _txt(el)[:60]
        n = int(m.group(1))
        if n in (1, 2):
            continue
        first.text = f"{n - 2}." + first.text[m.end():]
    elif i < start:
        for t in el.iter(db.qn("w:t")):
            if t.text and _cite.search(t.text):
                t.text = _cite.sub(_shift, t.text)
    keep_out.append(el)
b.out[:] = keep_out
b.save(OUT / "1_article" / "Мақала_KZ_Вестник_АРУ_v9_highlighted.docx")
